// ---------- helpers ----------
const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
const sma = (a, n) => a.length >= n ? avg(a.slice(-n)) : null;
const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const etDate = ts => new Date(ts * 1000).toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const rsi = (a, n = 14) => {
  if (a.length < n + 1) return null;
  let g = 0, l = 0;
  for (let i = a.length - n; i < a.length; i++) { const d = a[i] - a[i - 1]; if (d >= 0) g += d; else l -= d; }
  if (l === 0) return 100;
  return 100 - 100 / (1 + g / l);
};

// ---------- source 1: Yahoo Finance (price + 6 months history -> technicals) ----------
async function yahoo(sym) {
  const d = await http(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?interval=1d&range=6mo`, UA);
  const r = d?.chart?.result?.[0];
  if (!r || !r.timestamp) return null;
  const q = r.indicators.quote[0];
  const rows = r.timestamp.map((t, i) => ({ t, o: q.open[i], c: q.close[i], v: q.volume[i] })).filter(x => x.c != null);
  if (rows.length < 2) return null;
  const m = r.meta;
  const last = rows[rows.length - 1];
  const price = m.regularMarketPrice ?? last.c;
  const todayBar = etDate(last.t) === etDate(m.regularMarketTime);
  const prev = todayBar ? rows[rows.length - 2].c : last.c;
  const closes = rows.map(x => x.c);
  if (todayBar) closes[closes.length - 1] = price;
  const vols = (todayBar ? rows.slice(-21, -1) : rows.slice(-20)).map(x => x.v).filter(Boolean);
  const avgVol = vols.length ? avg(vols) : null;
  const lr = closes.slice(-21).map((c, i, arr) => i ? Math.log(c / arr[i - 1]) : null).slice(1);
  let vol20 = null;
  if (lr.length >= 15) { const mu = avg(lr); vol20 = Math.sqrt(lr.reduce((s, x) => s + (x - mu) ** 2, 0) / (lr.length - 1)) * Math.sqrt(252) * 100; }
  const change = price - prev;
  return {
    name: m.shortName || m.longName || sym,
    currency: m.currency || 'USD',
    price, prev, change,
    pct: prev ? (change / prev) * 100 : null,
    gapPct: todayBar && last.o && prev ? (last.o / prev - 1) * 100 : null,
    sma20: sma(closes, 20), sma50: sma(closes, 50), rsi: rsi(closes),
    ret1m: closes.length > 22 ? (price / closes[closes.length - 22] - 1) * 100 : null,
    hi52: m.fiftyTwoWeekHigh ?? null, lo52: m.fiftyTwoWeekLow ?? null, vol20,
    distHi: m.fiftyTwoWeekHigh ? (price / m.fiftyTwoWeekHigh - 1) * 100 : null,
    volRatio: todayBar && avgVol && last.v ? last.v / avgVol : null
  };
}

// ---------- source 2: Finnhub (independent quote, analyst consensus, company news) ----------
async function fhQuote(sym) {
  if (!fk) return null;
  const d = await http(`https://finnhub.io/api/v1/quote?symbol=${encodeURIComponent(sym)}&token=${fk}`);
  return d && d.c > 0 ? { price: d.c, pct: d.dp } : null;
}
async function analysts(sym) {
  if (!fk) return null;
  const d = await http(`https://finnhub.io/api/v1/stock/recommendation?symbol=${encodeURIComponent(sym)}&token=${fk}`);
  const r = Array.isArray(d) && d[0];
  if (!r) return null;
  const total = r.strongBuy + r.buy + r.hold + r.sell + r.strongSell;
  if (!total) return null;
  const score = (2 * r.strongBuy + r.buy - r.sell - 2 * r.strongSell) / total; // -2..+2
  const label = score >= 1.2 ? 'Strong Buy' : score >= 0.4 ? 'Buy' : score > -0.4 ? 'Hold' : score > -1.2 ? 'Sell' : 'Strong Sell';
  return { score, label, total, buy: r.strongBuy + r.buy, hold: r.hold, sell: r.sell + r.strongSell };
}
const POS = ['beat', 'beats', 'surge', 'soar', 'record', 'upgrade', 'raises', 'growth', 'strong', 'profit', 'jump', 'rally', 'outperform', 'wins', 'expands'];
const NEG = ['miss', 'misses', 'plunge', 'fall', 'falls', 'drop', 'downgrade', 'cut', 'lawsuit', 'probe', 'weak', 'loss', 'recall', 'layoff', 'layoffs', 'slump', 'warning', 'investigation', 'fraud'];
async function fhNews(sym) {
  if (!fk) return null;
  const to = new Date(), from = new Date(Date.now() - 3 * 864e5);
  const f = x => x.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
  const d = await http(`https://finnhub.io/api/v1/company-news?symbol=${encodeURIComponent(sym)}&from=${f(from)}&to=${f(to)}&token=${fk}`);
  if (!Array.isArray(d) || !d.length) return null;
  const items = d.slice(0, 20);
  const scores = items.map(n => {
    const words = (n.headline || '').toLowerCase().split(/[^a-z\-]+/);
    const s = words.filter(w => POS.includes(w)).length - words.filter(w => NEG.includes(w)).length;
    return Math.sign(s);
  });
  return { kw: clamp(avg(scores), -1, 1), top: { headline: items[0].headline, url: items[0].url, source: items[0].source }, count: items.length };
}

// ---------- source 3: Alpha Vantage (news sentiment scored per ticker) ----------
async function alpha(sym) {
  if (!ak) return null;
  const d = await http(`https://www.alphavantage.co/query?function=NEWS_SENTIMENT&tickers=${encodeURIComponent(sym)}&limit=50&apikey=${ak}`);
  if (!d || !Array.isArray(d.feed)) return null; // rate-limited or no coverage
  const vals = [];
  for (const art of d.feed) {
    const t = (art.ticker_sentiment || []).find(x => x.ticker === sym && Number(x.relevance_score) >= 0.3);
    if (t) vals.push(Number(t.ticker_sentiment_score));
  }
  return vals.length ? { score: avg(vals), count: vals.length } : null;
}


// ---------- source 4: analyst actions reported by finance news (upgrades / downgrades / price-target changes) ----------
const decode = s => String(s || '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
const parseRss = xml => [...String(xml || '').matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => {
  const g = t => { const x = m[1].match(new RegExp(`<${t}[^>]*>([\\s\\S]*?)</${t}>`)); return x ? decode(x[1].replace(/<!\[CDATA\[|\]\]>/g, '').trim()) : ''; };
  return { title: g('title'), link: g('link'), date: Date.parse(g('pubDate')), source: g('source') };
});
const httpText = async url => {
  try { return await this.helpers.httpRequest({ method: 'GET', url, headers: { ...UA, Accept: 'application/rss+xml, text/xml' }, json: false, timeout: 15000 }); }
  catch (e) { return null; }
};
const UP = [/upgrad/i, /rais\w*\s.*target/i, /(boost|lift|hike)\w*\s.*target/i, /initiat\w+.*\b(buy|overweight|outperform)\b/i, /reiterat\w+.*\b(buy|overweight|outperform)\b/i, /top pick/i];
const DOWN = [/downgrad/i, /(cut|lower|slash|trim)\w*\s.*target/i, /initiat\w+.*\b(sell|underweight|underperform)\b/i];
const CREDIT = /credit (rating|outlook)|\bdebt\b|\bbonds?\b|moody|fitch|s&p global|\bs&p (weighs|plans|cuts|lowers|downgrades)|sovereign/i;
const ROUNDUP = /upgrades\/downgrades|upgrades and downgrades|analyst (actions|moves)|stocks? (upgraded|downgraded) today/i;
const MULTI = /\b[A-Z]{2,5},\s*[A-Z]{2,5},\s*[A-Z]{2,5}/;
async function analystActions(sym, name) {
  const first = String(name || '').split(/[\s,.]+/)[0];
  const mentions = t => new RegExp(`\\b${sym.replace(/[^A-Z0-9]/g, '')}\\b`, 'i').test(t) || (first.length >= 4 && new RegExp(`\\b${first}\\b`, 'i').test(t));
  const q = encodeURIComponent(`${sym} stock (upgrade OR downgrade OR "price target" OR analyst) when:7d`);
  const [g, yh, ud] = await Promise.all([
    httpText(`https://news.google.com/rss/search?q=${q}&hl=en-US&gl=US&ceid=US:en`),
    httpText(`https://feeds.finance.yahoo.com/rss/2.0/headline?s=${encodeURIComponent(sym)}&region=US&lang=en-US`),
    fk ? http(`https://finnhub.io/api/v1/stock/upgrade-downgrade?symbol=${encodeURIComponent(sym)}&from=${new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10)}&token=${fk}`) : null // may be premium-only; ignored if unavailable
  ]);
  const cutoff = Date.now() - 7 * 864e5;
  const seen = new Set(); const acts = [];
  for (const it of [...parseRss(g), ...parseRss(yh).map(x => ({ ...x, source: x.source || 'Yahoo Finance' }))]) {
    if (!it.title || (it.date && it.date < cutoff) || !mentions(it.title)) continue;
    const title = it.title.replace(new RegExp(`\\s+-\\s+${(it.source || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`), '');
    const key = title.toLowerCase().slice(0, 60);
    if (seen.has(key)) continue;
    if (CREDIT.test(title) || ROUNDUP.test(title) || MULTI.test(title)) continue;   // credit ratings, roundups, multi-ticker lists
    const isDown = DOWN.some(r => r.test(title)), isUp = UP.some(r => r.test(title));
    if (isDown === isUp) continue;                                                     // neither, or mixed
    const dir = isDown ? -1 : 1;
    seen.add(key);
    acts.push({ dir, text: title, url: it.link, source: it.source || 'news', date: it.date || 0 });
  }
  if (Array.isArray(ud)) {
    for (const x of ud) {
      const dir = x.action === 'up' ? 1 : x.action === 'down' ? -1 : 0;
      if (dir) acts.push({ dir, text: `${x.company}: ${x.fromGrade || '—'} → ${x.toGrade}`, url: null, source: 'Finnhub', date: Date.parse(x.gradeTime) || 0 });
    }
  }
  if (!acts.length) return null;
  acts.sort((a, b) => b.date - a.date);
  const ups = acts.filter(a => a.dir > 0).length, downs = acts.filter(a => a.dir < 0).length;
  return { ups, downs, net: ups - downs, latest: acts.slice(0, 2) };
}

// ---------- scoring (-100..+100) ----------
function scoreIt(y, an, av, nw, act) {
  let s = 0; const why = [];
  if (y) {
    if (y.sma50 != null) { if (y.price > y.sma50) { s += 15; why.push('uptrend'); } else { s -= 15; why.push('downtrend'); } }
    if (y.sma20 != null && y.sma50 != null) s += y.sma20 > y.sma50 ? 10 : -10;
    if (y.rsi != null) {
      if (y.rsi < 30) { s += 10; why.push('oversold, may bounce'); }
      else if (y.rsi > 70) { s -= 10; why.push('overbought'); }
    }
    if (y.hi52 && y.price >= y.hi52 * 0.97) why.push('near yearly high');
    if (y.lo52 && y.price <= y.lo52 * 1.05) why.push('near yearly low');
  }
  if (an) { s += an.score * 10; why.push(`analysts say ${an.label}`); }
  if (act) { s += clamp(act.net, -3, 3) / 3 * 20; if (act.net > 0) why.push('analysts upgrading'); else if (act.net < 0) why.push('analysts cutting'); }
  let sentiment = null;
  if (av) { sentiment = av.score; s += clamp(av.score / 0.35, -1, 1) * 25; }
  else if (nw) { sentiment = nw.kw; s += nw.kw * 12; }
  if (sentiment != null && Math.abs(sentiment) > 0.1) why.push(sentiment > 0 ? 'positive news' : 'negative news');
  s = Math.round(clamp(s, -100, 100));
  const label = s >= 35 ? '🟢 Bullish' : s >= 15 ? '🟡 Leaning bullish' : s > -15 ? '⚪ Neutral' : s > -35 ? '🟠 Leaning bearish' : '🔴 Bearish';
  return { score: s, label, reasons: why };
}

async function analyze(sym, full, idx) {
  const y = await yahoo(sym);
  const [fq, an, nw, av, act] = await Promise.all([
    full ? fhQuote(sym) : null,
    analysts(sym),
    full ? fhNews(sym) : null,
    full && idx < 5 ? alpha(sym) : null,   // Alpha Vantage free tier = 25 calls/day
    analystActions(sym, y?.name)
  ]);
  const base = y || (fq ? { price: fq.price, change: null, pct: fq.pct, currency: 'USD', name: sym } : null);
  if (!base) return { symbol: sym, price: null, sources: 0, score: -999, reasons: [] };
  const sc = scoreIt(y, an, av, nw, act);
  const notes = [...sc.reasons];
  if (y && fq && Math.abs(y.price - fq.price) / fq.price > 0.01) notes.push('check price');
  const sources = [y, an, av || nw, act].filter(Boolean).length;   // data coverage, 0-4
  return { symbol: sym, ...base, change: base.change ?? 0, ...sc, reasons: notes, sources, news: nw?.top || null, acts: act, analyst: an ? { buy: an.buy, hold: an.hold, sell: an.sell, label: an.label } : null };
}

// ---------- run ----------
const watch = await Promise.all(inp.symbols.map((s, i) => analyze(s, true, i)));

let ideas = [];
if (cfg.enableScreener && inp.source !== 'slack') {
  const uni = String(cfg.screenerUniverse || '').split(',').map(s => s.trim().toUpperCase())
    .filter(s => s && !inp.symbols.includes(s)).slice(0, 25);
  const res = await Promise.all(uni.map(s => analyze(s, false, 99)));
  ideas = res.filter(r => r.price != null && r.sources >= 2 && r.score >= 25).sort((a, b) => b.score - a.score).slice(0, 3);
}

const [SPY, QQQ, VIX] = await Promise.all(['SPY', 'QQQ', '^VIX'].map(yahoo));
return [{ json: { mode: inp.mode, source: inp.source, pulse: { SPY, QQQ, VIX }, watch, ideas } }];

// Build Slack Report — turns the analysis into a Slack Block Kit message.
const d = $input.first().json;

// ---------- helpers ----------
const sg = n => (n > 0 ? '+' : n < 0 ? '−' : '') + Math.abs(n);
const pc = n => n == null ? '—' : `${n >= 0 ? '+' : '−'}${Math.abs(n).toFixed(1)}%`;
const px = r => (!r.currency || r.currency === 'USD') ? `$${r.price.toFixed(2)}` : `${r.price.toFixed(2)} ${r.currency}`;
const sigName = s => s >= 35 ? 'Bullish' : s >= 15 ? 'Lean bullish' : s > -15 ? 'Neutral' : s > -35 ? 'Lean bearish' : 'Bearish';
const sigIcon = s => s >= 35 ? '🟢' : s >= 15 ? '🟡' : s > -15 ? '⚪' : s > -35 ? '🟠' : '🔴';
const PRETTY = {
  'analysts upgrading': 'Recent analyst upgrades / target raises',
  'analysts cutting': 'Recent analyst downgrades / target cuts',
  'uptrend': 'Trading above 50-day average',
  'downtrend': 'Trading below 50-day average',
  'overbought': 'Overbought (RSI above 70)',
  'oversold, may bounce': 'Oversold (RSI below 30)',
  'near yearly high': 'Near 52-week high',
  'near yearly low': 'Near 52-week low',
  'positive news': 'Positive news flow',
  'negative news': 'Negative news flow',
  'check price': 'Data sources differ on price'
};
const pretty = t => t.startsWith('analysts say ') ? `Analyst consensus: ${t.slice(13)}` : (PRETTY[t] || t);
const drivers = r => [...(r.reasons || [])].filter(Boolean)
  .sort((a, b) => /analyst|news/.test(b) - /analyst|news/.test(a)).slice(0, 4).map(pretty);
const pad = (s, n) => String(s).padEnd(n), rpad = (s, n) => String(s).padStart(n);
const chunk = (arr, n) => arr.reduce((o, x, i) => (i % n ? o[o.length - 1].push(x) : o.push([x]), o), []);

const now = new Date();
const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', timeZone: 'America/New_York' });
const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: 'America/New_York' });
const title = { open: 'Market Open Report', close: 'Market Close Report' }[d.mode] || 'Stock Check';

// ---------- data ----------
const ok = d.watch.filter(r => r.price != null).sort((a, b) => b.score - a.score);
const bad = d.watch.filter(r => r.price == null).map(r => r.symbol);
const best = ok.filter(r => r.score >= 15);
const weak = ok.filter(r => r.score <= -15);
const mid = ok.length - best.length - weak.length;

// ---------- change since last report (workflow static data; persists on scheduled runs) ----------
let prev = {}, sd = null;
try { sd = $getWorkflowStaticData('global'); prev = sd.scores || {}; } catch (e) {}
const delta = r => prev[r.symbol] ? r.score - prev[r.symbol].score : null;
const dStr = x => x == null ? '—' : x === 0 ? '=' : `${x > 0 ? '▲' : '▼'}${Math.abs(x)}`;
const tierChanges = ok.filter(r => prev[r.symbol] && sigName(prev[r.symbol].score) !== sigName(r.score))
  .map(r => `${r.score > prev[r.symbol].score ? '▲' : '▼'} *${r.symbol}*  ${sigName(prev[r.symbol].score)} → ${sigName(r.score)}`);

// ---------- market tone ----------
const p = d.pulse || {};
const spy = p.SPY?.pct, qqq = p.QQQ?.pct, vix = p.VIX?.price;
let tone = null;
if (spy != null) {
  const lead = qqq == null ? '' : qqq > spy + 0.3 ? ' Technology is leading.' : qqq < spy - 0.3 ? ' Technology is lagging.' : '';
  tone = (spy <= -1 ? 'Broad sell-off.' : spy < -0.2 ? 'Risk-off session.' : spy >= 1 ? 'Broad rally.' : spy > 0.2 ? 'Risk-on session.' : 'Flat, range-bound session.') + lead;
  if (vix != null) tone += vix > 30 ? ` Volatility is very high (VIX ${vix.toFixed(1)}).` : vix > 20 ? ` Volatility is elevated (VIX ${vix.toFixed(1)}).` : ` Volatility is subdued (VIX ${vix.toFixed(1)}).`;
}

// ---------- blocks ----------
const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: `📈 ${title}`, emoji: true } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${dateStr}  •  ${timeStr} ET  •  ${ok.length} tickers analysed` }] });

const fields = [];
if (p.SPY) fields.push({ type: 'mrkdwn', text: `*S&P 500*\n${spy >= 0 ? '▲' : '▼'} ${pc(spy)}` });
if (p.QQQ) fields.push({ type: 'mrkdwn', text: `*Nasdaq 100*\n${qqq >= 0 ? '▲' : '▼'} ${pc(qqq)}` });
if (p.VIX) fields.push({ type: 'mrkdwn', text: `*Volatility (VIX)*\n${vix.toFixed(1)} · ${vix > 30 ? 'Very high' : vix > 20 ? 'Elevated' : 'Calm'}` });
if (fields.length) blocks.push({ type: 'section', fields });
if (tone) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `*Market tone:* ${tone}` }] });
blocks.push({ type: 'divider' });

// summary
if (ok.length) {
  const hi = ok[0], lo = ok[ok.length - 1];
  const head = best.length
    ? `*Highest signal: ${hi.symbol}* — ${sigName(hi.score)} (${sg(hi.score)})`
    : '*No strong opportunities right now* — nothing on your watchlist scores as favourable.';
  const low = ok.length > 1 && lo.score <= -15 ? `\n*Lowest signal: ${lo.symbol}* — ${sigName(lo.score)} (${sg(lo.score)})` : '';
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${head}${low}\n_${best.length} favourable  •  ${mid} neutral  •  ${weak.length} weak_` } });
}
if (tierChanges.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Since last report*\n' + tierChanges.join('\n') } });

// table 1: signal ranking
const h1 = `${pad('#', 3)}${pad('Symbol', 8)}${rpad('Price', 11)}${rpad('Day', 8)}  ${pad('Signal', 14)}${rpad('Score', 6)}${rpad('Δ', 5)}`;
const r1 = ok.map((r, i) => `${pad(i + 1, 3)}${pad(r.symbol, 8)}${rpad(px(r), 11)}${rpad(pc(r.pct), 8)}  ${pad(sigName(r.score), 14)}${rpad(sg(r.score), 6)}${rpad(dStr(delta(r)), 5)}`);
if (ok.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Signal ranking*\n```' + [h1, '-'.repeat(h1.length), ...r1].join('\n') + '```' } });

// table 2: momentum & risk
const extraH = d.mode === 'open' ? 'Gap' : d.mode === 'close' ? 'Vol×' : null;
const h2 = `${pad('Symbol', 8)}${rpad('1M', 8)}${rpad('RSI', 5)}${rpad('vs 52wH', 9)}${rpad('Vol', 6)}${rpad('Buy/Hold/Sell', 15)}${extraH ? rpad(extraH, 7) : ''}`;
const r2 = ok.map(r => {
  const an = r.analyst ? `${r.analyst.buy}/${r.analyst.hold}/${r.analyst.sell}` : '—';
  const extra = d.mode === 'open' ? rpad(pc(r.gapPct), 7) : d.mode === 'close' ? rpad(r.volRatio != null ? r.volRatio.toFixed(1) + 'x' : '—', 7) : '';
  return `${pad(r.symbol, 8)}${rpad(pc(r.ret1m), 8)}${rpad(r.rsi != null ? r.rsi.toFixed(0) : '—', 5)}${rpad(pc(r.distHi), 9)}${rpad(r.vol20 != null ? r.vol20.toFixed(0) + '%' : '—', 6)}${rpad(an, 15)}${extra}`;
});
if (ok.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Momentum & risk*  _(1M return · RSI-14 · distance from 52-wk high · annualised volatility · analyst split)_\n```' + [h2, '-'.repeat(h2.length), ...r2].join('\n') + '```' } });

// key drivers (chunked to stay under Slack's per-block text limit)
chunk(ok, 5).forEach((grp, i) => {
  const lines = grp.map(r => `${sigIcon(r.score)} *${r.symbol}* — ${r.name || ''}  _(data coverage ${r.sources}/4)_\n      ${drivers(r).join('  ·  ') || 'Limited data'}`);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: (i === 0 ? '*Key drivers*\n' : '') + lines.join('\n') } });
});
if (bad.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `⚠️ No data returned for: ${bad.join(', ')}` }] });

// screened ideas
if (d.ideas && d.ideas.length) {
  blocks.push({ type: 'divider' });
  const lines = d.ideas.map(r => `${sigIcon(r.score)} *${r.symbol}* — ${r.name || ''}\n      ${px(r)} (${pc(r.pct)})  •  ${sigName(r.score)} (${sg(r.score)})  •  ${drivers(r).slice(0, 3).join('  ·  ')}`);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*On the radar* _(screened outside your watchlist)_\n' + lines.join('\n') } });
}

blocks.push({ type: 'divider' });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '*Methodology:* score (−100 to +100) = trend ±25 · momentum ±10 · analyst consensus ±20 · rating changes ±20 · news sentiment ±25.  Sources: Yahoo Finance, Finnhub, Alpha Vantage, Google News.  For information only — not investment advice.' }] });

// save today's scores for the next report's "Δ" column
try { if (sd) { sd.scores = { ...prev }; for (const r of ok) sd.scores[r.symbol] = { score: r.score, ts: Date.now() }; } } catch (e) {}

const text = `${title}: ${best.length ? 'highest signal ' + ok[0].symbol : 'no strong signals'} (${best.length} favourable, ${mid} neutral, ${weak.length} weak)`;
return [{ json: { text, blocks } }];

// Slack answers HTTP 200 even on failure, so surface its error here.
const r = $input.first().json;
if (!r.ok) throw new Error(`Slack rejected the report: ${r.error || 'unknown error'}${r.needed ? ' (missing scope: ' + r.needed + ')' : ''}`);
return [{ json: { delivered: true, channel: r.channel, ts: r.ts } }];

// Resolve Briefing — decides pre-market vs post-market, and skips weekends/US holidays on scheduled runs.
const cfg = $('Config').first().json;
let source = 'schedule', arg = '';
try { arg = String($('Briefing Command').first().json.body.text || '').toLowerCase(); source = 'slack'; } catch (e) {}
if (source === 'schedule') { try { $('Manual: Briefing').first(); source = 'manual'; } catch (e) {} }

const now = new Date();
const et = o => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', ...o }).format(now);
const hour = Number(et({ hour: 'numeric', hour12: false })) % 24;
const weekday = et({ weekday: 'short' });

// /briefing pre | /briefing post ; otherwise by time of day
const mode = /pre|open|morning/.test(arg) ? 'premarket' : /post|close|wrap|after/.test(arg) ? 'postmarket' : (hour < 12 ? 'premarket' : 'postmarket');

if (source === 'schedule') {
  if (weekday === 'Sat' || weekday === 'Sun') return [];
  const fk = (cfg.finnhubKey && !String(cfg.finnhubKey).includes('YOUR_')) ? cfg.finnhubKey : null;
  if (fk) {
    try {
      const ms = await this.helpers.httpRequest({ method: 'GET', url: `https://finnhub.io/api/v1/stock/market-status?exchange=US&token=${fk}`, json: true, timeout: 10000 });
      if (ms && ms.holiday) return [];   // full-day US market holiday
    } catch (e) {}
  }
}
return [{ json: { mode, source } }];

// Collect Market Data — gathers every number the briefing needs.
// Sources: Yahoo Finance (indices, futures, sectors, macro, extended-hours movers) · CoinGecko (+ Yahoo fallback) & alternative.me (crypto)
//          Finnhub (earnings calendar, market news) · community Forex Factory feed (US economic calendar)
const cfg = $('Config').first().json;
const inp = $input.first().json;
const mode = inp.mode;
const UA = { 'User-Agent': 'Mozilla/5.0' };
const real = k => (k && !String(k).includes('YOUR_')) ? k : null;
const fk = real(cfg.finnhubKey);
const http = async (url, headers = {}) => { try { return await this.helpers.httpRequest({ method: 'GET', url, headers, json: true, timeout: 20000 }); } catch (e) { return null; } };
const list = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const batch = async (items, size, fn) => { const out = []; for (let i = 0; i < items.length; i += size) out.push(...await Promise.all(items.slice(i, i + size).map(fn))); return out; };

// ---- dates (New York) ----
const etDay = d => d.toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
const addDays = (iso, n) => { const d = new Date(iso + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const weekend = iso => [0, 6].includes(new Date(iso + 'T12:00:00Z').getUTCDay());
const now = new Date();
const today = etDay(now);
let nextDay = addDays(today, 1); while (weekend(nextDay)) nextDay = addDays(nextDay, 1);
let prevDay = addDays(today, -1); while (weekend(prevDay)) prevDay = addDays(prevDay, -1);
const target = (mode === 'premarket' && !weekend(today)) ? today : nextDay;   // the session being previewed

// ---- Yahoo helpers ----
const tzDay = (ts, tz) => new Date(ts * 1000).toLocaleDateString('en-CA', { timeZone: tz || 'America/New_York' });
async function quote(sym, name) {
  const d = await http(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?interval=1d&range=1mo`, UA);
  const r = d?.chart?.result?.[0];
  if (!r || !r.timestamp) return null;
  const closes = r.indicators.quote[0].close || [];
  const rows = r.timestamp.map((t, i) => ({ t, c: closes[i] })).filter(x => x.c != null);
  if (rows.length < 2) return null;
  const m = r.meta, last = rows[rows.length - 1];
  const price = m.regularMarketPrice ?? last.c;
  const todayBar = tzDay(last.t, m.exchangeTimezoneName) === tzDay(m.regularMarketTime, m.exchangeTimezoneName);
  const prev = todayBar ? rows[rows.length - 2].c : last.c;
  return { symbol: sym, name: name || m.shortName || sym, price, prev, chg: price - prev, pct: prev ? (price / prev - 1) * 100 : null };
}
const group = async defs => (await batch(defs, 12, ([s, n]) => quote(s, n))).filter(Boolean);

// extended-hours move: post-market vs regular close (post) or pre-market vs prior close (pre)
async function extQuote(sym) {
  const d = await http(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?interval=5m&range=1d&includePrePost=true`, UA);
  const r = d?.chart?.result?.[0];
  if (!r || !r.timestamp) return null;
  const c = r.indicators.quote[0].close || [];
  let i = c.length - 1; while (i >= 0 && c[i] == null) i--;
  if (i < 0) return null;
  const m = r.meta, lastTs = r.timestamp[i], reg = m.currentTradingPeriod?.regular;
  const base = mode === 'postmarket' ? m.regularMarketPrice : m.chartPreviousClose;
  if (!base) return null;
  if (reg) {
    if (mode === 'postmarket' && lastTs <= reg.end) return null;   // no after-hours trades yet
    if (mode === 'premarket' && lastTs >= reg.start) return null;  // regular session already running
  }
  return { symbol: sym, price: c[i], pct: (c[i] / base - 1) * 100 };
}

// ---- crypto ----
const FALLBACK = [['BTC-USD', 'BTC', 'Bitcoin'], ['ETH-USD', 'ETH', 'Ethereum'], ['SOL-USD', 'SOL', 'Solana'], ['XRP-USD', 'XRP', 'XRP'], ['BNB-USD', 'BNB', 'BNB'], ['DOGE-USD', 'DOGE', 'Dogecoin'], ['ADA-USD', 'ADA', 'Cardano'], ['AVAX-USD', 'AVAX', 'Avalanche'], ['LINK-USD', 'LINK', 'Chainlink'], ['TRX-USD', 'TRX', 'TRON']];
async function crypto() {
  const [cg, glob, fng] = await Promise.all([
    http(`https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids=${list(cfg.cryptoCoins).join(',')}&order=market_cap_desc&price_change_percentage=24h,7d`),
    http('https://api.coingecko.com/api/v3/global'),
    http('https://api.alternative.me/fng/?limit=2')
  ]);
  let coins = Array.isArray(cg) ? cg.map(c => ({ symbol: String(c.symbol).toUpperCase(), name: c.name, price: c.current_price, pct24: c.price_change_percentage_24h, pct7d: c.price_change_percentage_7d_in_currency, mcap: c.market_cap })) : [];
  if (!coins.length) {
    const q = await batch(FALLBACK, 10, async ([s, sym, nm]) => { const x = await quote(s, nm); return x && { symbol: sym, name: nm, price: x.price, pct24: x.pct, pct7d: null }; });
    coins = q.filter(Boolean);
  }
  const g = glob?.data;
  return {
    coins,
    global: g ? { mcap: g.total_market_cap?.usd, mcapPct24: g.market_cap_change_percentage_24h_usd, btcDom: g.market_cap_percentage?.btc, ethDom: g.market_cap_percentage?.eth } : null,
    fng: fng?.data?.[0] ? { value: Number(fng.data[0].value), label: fng.data[0].value_classification, prev: fng.data[1] ? Number(fng.data[1].value) : null } : null
  };
}

// ---- earnings (Finnhub) ----
const norm = e => ({ symbol: e.symbol, hour: e.hour, epsEst: e.epsEstimate, epsAct: e.epsActual, revEst: e.revenueEstimate, revAct: e.revenueActual,
  surprise: (e.epsActual != null && e.epsEstimate) ? (e.epsActual - e.epsEstimate) / Math.abs(e.epsEstimate) * 100 : null });
async function earnings() {
  if (!fk) return { reported: [], upcoming: [] };
  const get = async day => ((await http(`https://finnhub.io/api/v1/calendar/earnings?from=${day}&to=${day}&token=${fk}`))?.earningsCalendar || []).map(norm);
  const size = e => e.revAct || e.revEst || 0;
  const top = (a, n) => a.sort((x, y) => size(y) - size(x)).slice(0, n);
  if (mode === 'postmarket') {
    const [t, n] = await Promise.all([get(today), get(nextDay)]);
    return { reported: top(t.filter(e => e.epsAct != null), 8), upcoming: top(n, 8) };
  }
  const [p, t] = await Promise.all([get(prevDay), get(today)]);
  return { reported: top(p.filter(e => e.hour === 'amc' && e.epsAct != null), 6), upcoming: top(t, 10) };
}

// ---- US economic calendar (community Forex Factory feed) ----
async function events() {
  const feeds = await Promise.all(['thisweek', 'nextweek'].map(w => http(`https://nfs.faireconomy.media/ff_calendar_${w}.json`)));
  const all = feeds.filter(Array.isArray).flat().filter(e => e.country === 'USD' && ['High', 'Medium'].includes(e.impact));
  const row = e => ({ day: etDay(new Date(e.date)), time: new Date(e.date).toLocaleTimeString('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit' }), title: e.title, impact: e.impact, forecast: e.forecast, previous: e.previous });
  const seen = new Set();
  const rows = all.map(row).filter(e => { const k = `${e.day}|${e.time}|${e.title}`; return seen.has(k) ? false : (seen.add(k), true); });
  return { target: rows.filter(e => e.day === target), ahead: rows.filter(e => e.day > target && e.impact === 'High').slice(0, 6) };
}

// ---- run ----
const [us, futures, asia, europe, macro, sectors, cr, earn, news, ev] = await Promise.all([
  group([['^GSPC', 'S&P 500'], ['^DJI', 'Dow Jones'], ['^IXIC', 'Nasdaq Comp.'], ['^RUT', 'Russell 2000'], ['^VIX', 'VIX']]),
  group([['ES=F', 'S&P 500 fut.'], ['NQ=F', 'Nasdaq 100 fut.'], ['YM=F', 'Dow fut.'], ['RTY=F', 'Russell fut.']]),
  group([['^N225', 'Nikkei 225'], ['^HSI', 'Hang Seng'], ['000001.SS', 'Shanghai Comp.'], ['^KS11', 'Kospi'], ['^AXJO', 'ASX 200'], ['^NSEI', 'Nifty 50']]),
  group([['^STOXX', 'STOXX 600'], ['^GDAXI', 'DAX'], ['^FTSE', 'FTSE 100'], ['^FCHI', 'CAC 40']]),
  group([['^TNX', 'US 10Y yield'], ['CL=F', 'WTI crude'], ['GC=F', 'Gold'], ['DX-Y.NYB', 'Dollar index']]),
  group([['XLK', 'Technology'], ['XLF', 'Financials'], ['XLV', 'Health Care'], ['XLY', 'Consumer Disc.'], ['XLP', 'Consumer Staples'], ['XLE', 'Energy'], ['XLI', 'Industrials'], ['XLB', 'Materials'], ['XLU', 'Utilities'], ['XLRE', 'Real Estate'], ['XLC', 'Comm. Services']]),
  crypto(),
  earnings(),
  fk ? http(`https://finnhub.io/api/v1/news?category=general&token=${fk}`) : null,
  events()
]);

const headlines = Array.isArray(news) ? news.filter(x => x.datetime * 1000 > Date.now() - 30 * 3600e3).slice(0, 15).map(x => x.headline) : [];

// extended-hours movers across a universe (mega caps + watchlist + today's reporters)
const universe = [...new Set([...list(cfg.moversUniverse), ...list(cfg.watchlist), ...earn.reported.map(e => e.symbol), ...earn.upcoming.map(e => e.symbol)])].slice(0, 60);
const ext = (await batch(universe, 10, extQuote)).filter(Boolean).filter(x => Math.abs(x.pct) >= 0.5);
const movers = { up: ext.filter(x => x.pct > 0).sort((a, b) => b.pct - a.pct).slice(0, 6), down: ext.filter(x => x.pct < 0).sort((a, b) => a.pct - b.pct).slice(0, 6) };

return [{ json: { mode, source: inp.source, today, target, us, futures, asia, europe, macro, sectors, crypto: cr, earnings: earn, news: headlines, events: ev, movers } }];

// AI Commentary — optional. Uses Claude with web search to research the parts no free API covers
// (crypto ETF flows, crypto developments, macro/world news, earnings colour, outlook). Falls back silently if disabled or failing.
const cfg = $('Config').first().json;
const d = $input.first().json;
const ak = (cfg.anthropicKey && !String(cfg.anthropicKey).includes('YOUR_')) ? cfg.anthropicKey : null;
if (!ak || cfg.enableAI === false) return [{ json: { ...d, ai: null, aiNote: 'AI commentary off' } }];

const r2 = n => n == null ? null : Math.round(n * 100) / 100;
const slim = a => (a || []).map(x => ({ n: x.name, p: r2(x.price), c: r2(x.pct) }));
const pre = d.mode === 'premarket';
const etNow = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'full', timeStyle: 'short' });
const data = {
  us: slim(d.us), futures: slim(d.futures), asia: slim(d.asia), europe: slim(d.europe), macro: slim(d.macro), sectors: slim(d.sectors),
  crypto: { coins: d.crypto.coins.map(c => ({ s: c.symbol, p: r2(c.price), c24: r2(c.pct24), c7d: r2(c.pct7d) })), global: d.crypto.global, fearGreed: d.crypto.fng },
  earnings: d.earnings, economicEvents: d.events, headlines: d.news.slice(0, 12), extendedHoursMovers: d.movers
};

const schema = `{
  "summary": "3-4 sentence executive summary of the session / overnight picture",
  "macroNews": ["max 5 key world & macro stories from the past ~24h, one line each"],
  "earnings": ["max 6 lines: ${pre ? "key reports scheduled today with consensus, plus notable results released after yesterday's close" : "key results released today with beat/miss and guidance reaction"}"],
  "moverNotes": ["max 6 lines explaining WHY the biggest ${pre ? 'pre-market' : 'after-hours'} movers are moving (ticker first)"],
  "crypto": {
    "summary": "2-3 sentences on Bitcoin, Ethereum and major altcoins",
    "etfFlows": "latest daily net flows for US spot Bitcoin and Ether ETFs (and others if available) with the date; say 'not available' if you cannot verify",
    "developments": ["max 4 key crypto developments from the past day"]
  },
  "upcoming": ["max 6 important events for ${pre ? 'today' : 'the next trading session'} (earnings, data, Fed speakers, auctions, geopolitics)"],
  "outlook": { "bias": "Constructive | Neutral | Cautious", "base": "base-case path for ${pre ? 'the US open and today' : 'the next session'}", "bull": "what would drive upside", "bear": "what would drive downside", "levels": "key S&P 500 / Nasdaq levels to watch" },
  "focus": ["max 5 sectors, themes or stocks to watch, each with a short reason"]
}`;

const system = `You are a senior markets analyst writing a concise, factual ${pre ? 'pre-market briefing' : 'post-market wrap-up'} for a professional audience.
Rules: (1) Use the web_search tool to verify and enrich — never invent figures, quotes or events; if you cannot verify something, omit it or say "not available". (2) Today is ${etNow} (New York time). Only include events from the relevant window. (3) Outlook is scenario-based and probabilistic, never a guarantee, and contains no personalised investment advice. (4) No URLs, no source names, no markdown. (5) Keep every string under 220 characters. (6) Respond with ONE JSON object only, matching the schema exactly.`;

const user = `Create the ${pre ? 'PRE-MARKET BRIEFING for today\'s US open' : 'POST-MARKET WRAP-UP for today\'s US session'}.\n\nQuantitative data already collected (percent changes are for the latest session/overnight):\n${JSON.stringify(data)}\n\nResearch with web search: US/global market drivers, crypto ETF flows (spot Bitcoin/Ether), major crypto developments in the last 24h, key macro/world news, notable earnings reactions and ${pre ? 'pre-market' : 'after-hours'} movers, and the calendar for ${pre ? 'today' : 'the next session'}.\n\nSchema:\n${schema}`;

let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages', json: true, timeout: 240000,
    headers: { 'x-api-key': ak, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: { model: cfg.aiModel || 'claude-sonnet-5-5', max_tokens: 4000, system,
      tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 8 }],
      messages: [{ role: 'user', content: user }] }
  });
} catch (e) { return [{ json: { ...d, ai: null, aiNote: 'AI request failed: ' + String(e.message || e).slice(0, 200) } }]; }

const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
let ai = null;
try { ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) {}
return [{ json: { ...d, ai, aiNote: ai ? 'ok' : 'AI reply was not valid JSON' } }];

// Build Briefing Report — Slack Block Kit message with QuickChart graphs.
const cfg = $('Config').first().json;
const d = $input.first().json;
const ai = d.ai || {};
const pre = d.mode === 'premarket';

// ---------- helpers ----------
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n = 230) => s.length > n ? s.slice(0, n - 1) + '…' : s;
const arr = x => Array.isArray(x) ? x.filter(Boolean).map(v => clip(esc(typeof v === 'string' ? v : JSON.stringify(v)))) : [];
const txt = x => x ? clip(esc(String(x)), 500) : '';
const pc = n => n == null ? '—' : `${n >= 0 ? '+' : '−'}${Math.abs(n).toFixed(2)}%`;
const num = (n, dp = 2) => n == null ? '—' : Number(n).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
const big = n => n == null ? '—' : n >= 1e12 ? `$${(n / 1e12).toFixed(2)}T` : n >= 1e9 ? `$${(n / 1e9).toFixed(1)}B` : `$${num(n, 0)}`;
const pad = (s, n) => String(s).padEnd(n), rpad = (s, n) => String(s).padStart(n);
const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
const code = lines => '```' + lines.join('\n') + '```';
const section = (title, lines) => ({ type: 'section', text: { type: 'mrkdwn', text: clip(`*${title}*\n` + lines.join('\n'), 2900) } });
const bullets = a => a.map(x => `• ${x}`);
const find = (a, name) => (a || []).find(x => x.name === name);
const ICON = pct => pct == null ? '⚪' : pct >= 0 ? '🟢' : '🔴';

const now = new Date();
const dateStr = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', timeZone: 'America/New_York' });
const timeStr = now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: 'America/New_York' });
const title = pre ? '🌅 Pre-Market Briefing' : '🌇 Post-Market Wrap-Up';

const postJson = async (url, body) => { try { return await this.helpers.httpRequest({ method: 'POST', url, body, json: true, timeout: 20000 }); } catch (e) { return null; } };

// ---------- charts (QuickChart) ----------
async function chart(heading, items, values) {
  if (cfg.enableCharts === false || !items.length) return null;
  const config = {
    type: 'bar',
    data: { labels: items.map((x, i) => `${x}  ${pc(values[i])}`), datasets: [{ data: values.map(v => Math.round(v * 100) / 100), backgroundColor: values.map(v => v >= 0 ? '#2e9e5b' : '#d64545'), borderRadius: 3 }] },
    options: { indexAxis: 'y', plugins: { legend: { display: false }, title: { display: true, text: heading, font: { size: 16 } } }, scales: { x: { title: { display: true, text: '% change' }, grid: { color: '#e6e6e6' } }, y: { grid: { display: false } } } }
  };
  const r = await postJson('https://quickchart.io/chart/create', { chart: config, width: 720, height: 90 + items.length * 30, backgroundColor: 'white', version: '3', format: 'png' });
  return r && r.success && r.url ? { type: 'image', image_url: r.url, alt_text: heading, title: { type: 'plain_text', text: heading } } : null;
}

// ---------- data shortcuts ----------
const usIdx = d.us.filter(x => x.name !== 'VIX');
const vix = find(d.us, 'VIX');
const y10 = find(d.macro, 'US 10Y yield');
const sectors = [...d.sectors].sort((a, b) => b.pct - a.pct);
const coins = d.crypto.coins;
const spy = find(d.us, 'S&P 500'), ndx = find(d.us, 'Nasdaq Comp.'), dow = find(d.us, 'Dow Jones');
const futAvg = avg(d.futures.map(x => x.pct).filter(x => x != null));
const leadPct = pre ? futAvg : spy?.pct;

// ---------- rule-based fallbacks ----------
const fbSummary = pre
  ? `US futures point to a ${futAvg == null ? 'flat' : futAvg > 0.3 ? 'higher' : futAvg < -0.3 ? 'lower' : 'mixed'} open (S&P 500 ${pc(find(d.futures, 'S&P 500 fut.')?.pct)}, Nasdaq 100 ${pc(find(d.futures, 'Nasdaq 100 fut.')?.pct)}). Asia and Europe: ${[find(d.asia, 'Nikkei 225'), find(d.asia, 'Hang Seng'), find(d.europe, 'DAX')].filter(Boolean).map(x => `${x.name} ${pc(x.pct)}`).join(', ') || 'n/a'}.${vix ? ` VIX ${num(vix.price, 1)}.` : ''}`
  : `S&P 500 ${pc(spy?.pct)} to ${num(spy?.price)}, Nasdaq ${pc(ndx?.pct)}, Dow ${pc(dow?.pct)}.${sectors.length ? ` ${sectors[0].name} led (${pc(sectors[0].pct)}) while ${sectors[sectors.length - 1].name} lagged (${pc(sectors[sectors.length - 1].pct)}).` : ''}${vix ? ` VIX ${num(vix.price, 1)}.` : ''}`;
const bias = (vix && vix.price > 25) || (leadPct != null && leadPct < -0.7) ? 'Cautious' : (leadPct != null && leadPct > 0.5 && (!vix || vix.price < 22)) ? 'Constructive' : 'Neutral';
const fbOutlook = {
  bias,
  base: pre ? `Futures imply a ${leadPct == null ? 'flat' : leadPct >= 0 ? 'firmer' : 'softer'} open (${pc(leadPct)}); expect headline-driven trading around the open.` : `Momentum from today (${pc(spy?.pct)}) may carry into the open, but follow-through depends on overnight Asia/Europe and futures.`,
  bull: 'Easing yields or oil, strong earnings/guidance and calm volatility would support further gains.',
  bear: 'Higher yields, hawkish central-bank signals or disappointing guidance would pressure risk assets.',
  levels: spy ? `S&P 500 reference range ${num(spy.price * 0.99, 0)}–${num(spy.price * 1.01, 0)} (±1%).` : ''
};
const o = { ...fbOutlook, ...(ai.outlook || {}) };

// ---------- blocks ----------
const blocks = [];
blocks.push({ type: 'header', text: { type: 'plain_text', text: title, emoji: true } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${dateStr}  •  ${timeStr} ET  •  ${pre ? 'ahead of the US open' : 'after the US close'}` }] });

// executive summary + snapshot
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Executive summary*\n${txt(ai.summary) || esc(fbSummary)}` } });
const snap = [];
if (pre) {
  const s = find(d.futures, 'S&P 500 fut.'), n = find(d.futures, 'Nasdaq 100 fut.');
  if (s) snap.push(`*S&P 500 futures*\n${ICON(s.pct)} ${pc(s.pct)}`);
  if (n) snap.push(`*Nasdaq 100 futures*\n${ICON(n.pct)} ${pc(n.pct)}`);
} else {
  if (spy) snap.push(`*S&P 500*\n${ICON(spy.pct)} ${num(spy.price)}  (${pc(spy.pct)})`);
  if (ndx) snap.push(`*Nasdaq*\n${ICON(ndx.pct)} ${num(ndx.price)}  (${pc(ndx.pct)})`);
}
if (vix) snap.push(`*VIX*\n${num(vix.price, 1)}  (${pc(vix.pct)})`);
if (y10) snap.push(`*US 10Y yield*\n${num(y10.price, 3)}%  (${y10.chg >= 0 ? '+' : '−'}${Math.abs(y10.chg * 100).toFixed(1)} bp)`);
if (snap.length) blocks.push({ type: 'section', fields: snap.map(t => ({ type: 'mrkdwn', text: t })) });
blocks.push({ type: 'divider' });

// markets: charts first (parallel), then tables
const idxItems = pre ? [...d.futures, ...d.europe, ...d.asia] : [...usIdx, ...d.europe, ...d.asia];
const [chIdx, chSec, chCrypto] = await Promise.all([
  chart(pre ? 'Overnight: US futures, Europe & Asia' : 'Index performance: US close, Europe & Asia', idxItems.map(x => x.name), idxItems.map(x => x.pct ?? 0)),
  chart('S&P 500 sectors (SPDR ETFs)', sectors.map(x => x.name), sectors.map(x => x.pct ?? 0)),
  chart('Crypto: 24h change', coins.map(c => c.symbol), coins.map(c => c.pct24 ?? 0))
]);

const row = x => `${pad(x.name, 17)}${rpad(num(x.price), 11)}${rpad(pc(x.pct), 9)}`;
const mkt = [];
if (pre) { mkt.push('US FUTURES', ...d.futures.map(row), '', 'ASIA (closed)', ...d.asia.map(row), '', 'EUROPE', ...d.europe.map(row)); }
else { mkt.push('US CLOSE', ...d.us.map(row), '', 'EUROPE', ...d.europe.map(row), '', 'ASIA', ...d.asia.map(row)); }
mkt.push('', 'RATES · COMMODITIES · FX', ...d.macro.map(x => x.name === 'US 10Y yield' ? `${pad(x.name, 17)}${rpad(num(x.price, 3) + '%', 11)}${rpad((x.chg >= 0 ? '+' : '−') + Math.abs(x.chg * 100).toFixed(1) + 'bp', 9)}` : row(x)));
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${pre ? 'Overnight global markets' : 'Global market close'}*\n${code(mkt)}` } });
if (chIdx) blocks.push(chIdx);

// sectors
if (sectors.length) {
  const top = sectors.slice(0, 3).map(x => `${x.name} ${pc(x.pct)}`).join('  ·  ');
  const bot = sectors.slice(-3).reverse().map(x => `${x.name} ${pc(x.pct)}`).join('  ·  ');
  blocks.push({ type: 'divider' });
  blocks.push(section(pre ? 'Sector performance (last session)' : 'Sector winners & losers', [`🟢 *Leaders:* ${top}`, `🔴 *Laggards:* ${bot}`]));
  if (chSec) blocks.push(chSec);
}

// crypto
blocks.push({ type: 'divider' });
const cRows = [`${pad('Coin', 7)}${rpad('Price', 13)}${rpad('24h', 9)}${rpad('7d', 9)}`, ...coins.map(c => `${pad(c.symbol, 7)}${rpad('$' + num(c.price, c.price < 10 ? 4 : 2), 13)}${rpad(pc(c.pct24), 9)}${rpad(pc(c.pct7d), 9)}`)];
const cg = d.crypto.global, fng = d.crypto.fng, cai = ai.crypto || {};
const cMeta = [];
if (cg?.mcap) cMeta.push(`Total market cap ${big(cg.mcap)} (${pc(cg.mcapPct24)} 24h)`);
if (cg?.btcDom) cMeta.push(`BTC dominance ${cg.btcDom.toFixed(1)}%`);
if (fng) cMeta.push(`Fear & Greed ${fng.value} — ${fng.label}${fng.prev != null ? ` (prev ${fng.prev})` : ''}`);
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Crypto landscape*\n${code(cRows)}${cMeta.length ? '\n' + cMeta.join('  •  ') : ''}` } });
if (chCrypto) blocks.push(chCrypto);
const cLines = [];
if (cai.summary) cLines.push(txt(cai.summary));
if (cai.etfFlows) cLines.push(`📊 *ETF flows:* ${txt(cai.etfFlows)}`);
arr(cai.developments).forEach(x => cLines.push(`• ${x}`));
if (cLines.length) blocks.push(section('Crypto: ETF flows & key developments', cLines));

// macro & world news
blocks.push({ type: 'divider' });
const macroLines = arr(ai.macroNews).length ? arr(ai.macroNews) : d.news.slice(0, 5).map(h => clip(esc(h)));
if (macroLines.length) blocks.push(section('Macro & world news (past 24h)', bullets(macroLines)));

// earnings
const eLines = [];
const fmtE = e => `*${e.symbol}*${e.hour ? ` (${e.hour === 'bmo' ? 'pre-mkt' : e.hour === 'amc' ? 'after close' : e.hour})` : ''}${e.epsAct != null ? ` EPS ${num(e.epsAct)} vs ${num(e.epsEst)} est${e.surprise != null ? ` → ${e.surprise >= 0 ? '✅ beat' : '❌ miss'} ${pc(e.surprise)}` : ''}` : (e.epsEst != null ? ` EPS est ${num(e.epsEst)}` : '')}`;
if (d.earnings.reported.length) { eLines.push(pre ? '_Reported after yesterday\'s close:_' : '_Reported today:_'); d.earnings.reported.forEach(e => eLines.push(`• ${fmtE(e)}`)); }
if (d.earnings.upcoming.length) { eLines.push(pre ? '_Scheduled today:_' : '_Scheduled next session:_'); d.earnings.upcoming.slice(0, 6).forEach(e => eLines.push(`• ${fmtE(e)}`)); }
arr(ai.earnings).forEach(x => eLines.push(`• ${x}`));
if (eLines.length) blocks.push(section('Key earnings', eLines));

// movers
const mv = x => `${x.pct >= 0 ? '▲' : '▼'} *${x.symbol}* ${pc(x.pct)} ($${num(x.price)})`;
const mLines = [];
if (d.movers.up.length) mLines.push('🟢 ' + d.movers.up.map(mv).join('   '));
if (d.movers.down.length) mLines.push('🔴 ' + d.movers.down.map(mv).join('   '));
arr(ai.moverNotes).forEach(x => mLines.push(`• ${x}`));
if (mLines.length) blocks.push(section(pre ? 'Pre-market movers' : 'Notable after-hours movers', mLines));

// upcoming events
blocks.push({ type: 'divider' });
const uLines = [];
const impact = e => e.impact === 'High' ? '🔴' : '🟠';
d.events.target.forEach(e => uLines.push(`${impact(e)} ${e.time} ET — ${esc(e.title)}${e.forecast ? ` (fcst ${esc(e.forecast)}${e.previous ? `, prev ${esc(e.previous)}` : ''})` : ''}`));
arr(ai.upcoming).forEach(x => uLines.push(`• ${x}`));
if (d.events.ahead.length) { uLines.push('_Later this week / next week:_'); d.events.ahead.slice(0, 4).forEach(e => uLines.push(`${impact(e)} ${e.day.slice(5)} ${e.time} — ${esc(e.title)}`)); }
if (uLines.length) blocks.push(section(pre ? 'Today\'s calendar' : 'Next session: what to watch', uLines));

// outlook & focus
const focusFb = [sectors[0] && `${sectors[0].name} (relative strength)`, sectors.length > 1 && `${sectors[sectors.length - 1].name} (weakness — watch for stabilisation)`, (d.movers.up[0] || d.movers.down[0]) && `${(d.movers.up[0] || d.movers.down[0]).symbol} (largest ${pre ? 'pre-market' : 'after-hours'} move)`].filter(Boolean);
const focus = arr(ai.focus).length ? arr(ai.focus) : focusFb;
blocks.push(section(`Short-term outlook — ${pre ? 'today' : 'next session'}`, [
  `*Bias:* ${txt(o.bias) || 'Neutral'}`, `*Base case:* ${txt(o.base)}`, `⬆️ *Upside:* ${txt(o.bull)}`, `⬇️ *Downside:* ${txt(o.bear)}`, o.levels ? `📍 *Levels:* ${txt(o.levels)}` : ''
].filter(Boolean)));
if (focus.length) blocks.push(section('Focus areas', bullets(focus)));

blocks.push({ type: 'divider' });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Data: Yahoo Finance, CoinGecko, Finnhub, alternative.me, community economic calendar.${ai.summary ? ' News, ETF flows and outlook are AI-assisted (Claude with web search) — verify before acting.' : ' AI commentary was not available for this run.'}  Scenarios, not predictions. For information only — not investment advice.` }] });

const text = `${pre ? 'Pre-Market Briefing' : 'Post-Market Wrap-Up'}: ${(txt(ai.summary) || fbSummary).slice(0, 180)}`;
return [{ json: { text, blocks: blocks.slice(0, 50), channel: cfg.briefingChannelId || '', aiNote: d.aiNote } }];
